/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    readSavePerkIndex, sortedUniquePerkIndices, computeUnbannedPerkIndices, readSavePerkOrderList, readPerkChoicesFromSaveRoot
 * depends    src/save/access/values, src/save/catalogs/perks, src/save/perks/types
 * used by    src/calculators/specs.generated, src/save/perks/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

import { listActivePerkIndices } from '../catalogs/perks'
import {
  coerceSaveNumber,
  readSaveBoolean,
  readSaveNumberSource,
  toNumberArray,
} from '../access/values'
import type { SavePerkChoices } from './types'

export function readSavePerkIndex(value: unknown): number | null {
  const parsed = coerceSaveNumber(value)
  if (parsed == null) return null
  return Math.floor(parsed)
}

export function sortedUniquePerkIndices(indices: Iterable<number>): number[] {
  return [...new Set(indices)].sort((left, right) => left - right)
}

export function computeUnbannedPerkIndices(
  bannedIndices: readonly number[],
  activeIndices: readonly number[] = listActivePerkIndices(),
): number[] {
  const banned = new Set(bannedIndices)
  return activeIndices.filter(index => !banned.has(index))
}

/** Unity perk order lists may use -1 for empty slots; do not coerce those to index 0. */
export function readSavePerkOrderList(raw: unknown): number[] {
  const out: number[] = []
  for (const item of readSaveNumberSource(raw)) {
    const parsed = coerceSaveNumber(item)
    if (parsed == null || parsed < 0) continue
    out.push(Math.floor(parsed))
  }
  return out
}

/**
 * The perk choices a save records, read from their save fields and nothing more.
 *
 * Which fields hold the bans and the auto-pick order is save-format knowledge, so it lives here.
 * Shaping these into what a tool persists — names resolved, defaults filled — is the tool's job.
 */
export function readPerkChoicesFromSaveRoot(
  root: Record<string, unknown> | null | undefined,
): SavePerkChoices | null {
  if (!root) return null
  const firstPerkRaw = readSavePerkIndex(root.firstPerkIndex)
  const firstTradeOffRaw = readSavePerkIndex(root.firstTradeOffPerkIndex)
  return {
    bannedIndices: sortedUniquePerkIndices(toNumberArray(root.bannedPerksIndex)),
    firstPerkIndex: firstPerkRaw == null || firstPerkRaw < 0 ? null : firstPerkRaw,
    firstTradeOffPerkIndex: firstTradeOffRaw == null || firstTradeOffRaw < 0 ? null : firstTradeOffRaw,
    autoPickPerk: readSaveBoolean(root.autoPickPerk),
    autoPickOrder: readSavePerkOrderList(root.autoPickOrder),
  }
}
